function getWeekday(dateString) {
    // 创建日期对象
    const date = new Date(dateString);

    // 检查日期是否有效
    if (isNaN(date.getTime())) {
        return "无效的日期格式";
    }

    // 星期数组（注意：JavaScript中getDay()返回0-6，0代表星期日）
    const weekdays = ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"];

    // 获取星期几并返回
    return weekdays[date.getDay()];
}

// 使用示例
console.log(getWeekday("2024-01-15")); // 输出：星期一
console.log(getWeekday("2024-01-20")); // 输出：星期六
console.log(getWeekday("2024-01-21")); // 输出：星期日
```

### 代码说明：
1. **创建日期对象**：使用 `new Date(dateString)` 将字符串转换为日期对象
2. **有效性检查**：使用 `isNaN(date.getTime())` 检查日期是否有效
3. **星期数组**：定义包含中文星期名称的数组（索引0对应星期日）
4. **获取星期**：使用 `getDay()` 方法获取0-6的数字，作为数组索引返回对应的中文星期

### 注意事项：
- 输入格式必须是 `"YYYY-MM-DD"`（如 `"2024-01-15"`）
- 如果输入无效日期，函数会返回 `"无效的日期格式"`
- 在JavaScript中，`getDay()` 返回 `0` 表示星期日，`1` 表示星期一，以此类推

